/**
 * Business-hours-aware time math.
 *
 * Zero dependencies: uses only Intl, so the exact same code runs in Node (tests)
 * and inside n8n Code nodes (the build script inlines this file).
 *
 * Hours config:
 *   {
 *     timezone:  'America/New_York',
 *     startTime: '09:00',
 *     endTime:   '17:00',
 *     workdays:  [1, 2, 3, 4, 5],     // ISO weekdays: 1 = Mon ... 7 = Sun
 *     holidays:  ['2026-12-25']       // local dates (YYYY-MM-DD) with no business hours
 *   }
 */

const MS_PER_MINUTE = 60 * 1000;
const MAX_DAYS_SCANNED = 800;

const DEFAULT_HOURS = {
  timezone: 'America/New_York',
  startTime: '09:00',
  endTime: '17:00',
  workdays: [1, 2, 3, 4, 5],
  holidays: [],
};

const _formatters = {};

function getFormatter(timeZone) {
  if (!_formatters[timeZone]) {
    _formatters[timeZone] = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  }
  return _formatters[timeZone];
}

/** Wall-clock parts of an instant in a given IANA time zone. */
function zonedParts(ms, timeZone) {
  const out = {};
  for (const p of getFormatter(timeZone).formatToParts(new Date(ms))) out[p.type] = p.value;
  return {
    year: Number(out.year),
    month: Number(out.month),
    day: Number(out.day),
    hour: Number(out.hour) % 24,
    minute: Number(out.minute),
    second: Number(out.second),
  };
}

/** Offset (ms) of a zone from UTC at a given instant. Positive = ahead of UTC. */
function tzOffsetMs(ms, timeZone) {
  const p = zonedParts(ms, timeZone);
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
  return asUtc - Math.floor(ms / 1000) * 1000;
}

/** Convert a local wall-clock time in `timeZone` to a UTC epoch (ms). DST-safe. */
function localToUtcMs(year, month, day, hour, minute, timeZone) {
  const guess = Date.UTC(year, month - 1, day, hour, minute, 0);
  const offset = tzOffsetMs(guess, timeZone);
  let utc = guess - offset;
  const offset2 = tzOffsetMs(utc, timeZone);
  if (offset2 !== offset) utc = guess - offset2;
  return utc;
}

function parseHHMM(value) {
  const m = /^(\d{1,2}):(\d{2})$/.exec(String(value).trim());
  if (!m || Number(m[1]) > 24 || Number(m[2]) > 59) {
    throw new Error(`Invalid time "${value}" - expected HH:MM (24h)`);
  }
  return { hour: Number(m[1]), minute: Number(m[2]) };
}

function normalizeHours(hours) {
  const h = Object.assign({}, DEFAULT_HOURS, hours || {});
  try {
    getFormatter(h.timezone);
  } catch (e) {
    throw new Error(`Invalid time zone "${h.timezone}" - use an IANA name like "America/New_York"`);
  }
  const start = parseHHMM(h.startTime);
  const end = parseHHMM(h.endTime);
  if (end.hour * 60 + end.minute <= start.hour * 60 + start.minute) {
    throw new Error('Business hours endTime must be after startTime');
  }
  const workdays = (h.workdays || []).map(Number);
  if (!workdays.length || workdays.some((d) => !(d >= 1 && d <= 7))) {
    throw new Error('workdays must be ISO weekdays 1 (Mon) to 7 (Sun)');
  }
  return {
    timezone: h.timezone,
    start,
    end,
    workdays,
    holidays: (h.holidays || []).map(String),
  };
}

const pad2 = (n) => String(n).padStart(2, '0');

function isBusinessDay(y, m, d, cfg) {
  const iso = new Date(Date.UTC(y, m - 1, d)).getUTCDay() || 7;
  return cfg.workdays.includes(iso) && !cfg.holidays.includes(`${y}-${pad2(m)}-${pad2(d)}`);
}

function nextDay(y, m, d) {
  const dt = new Date(Date.UTC(y, m - 1, d + 1));
  return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
}

function dayWindow(y, m, d, cfg) {
  return {
    open: localToUtcMs(y, m, d, cfg.start.hour, cfg.start.minute, cfg.timezone),
    close: localToUtcMs(y, m, d, cfg.end.hour, cfg.end.minute, cfg.timezone),
  };
}

/** Is this instant inside business hours? */
function isWithinBusinessHours(ms, hours) {
  const cfg = normalizeHours(hours);
  const p = zonedParts(ms, cfg.timezone);
  if (!isBusinessDay(p.year, p.month, p.day, cfg)) return false;
  const w = dayWindow(p.year, p.month, p.day, cfg);
  return ms >= w.open && ms < w.close;
}

/**
 * Business minutes elapsed between two instants.
 * Time outside business hours, on non-working days, and on holidays does not count.
 */
function businessMinutesBetween(startMs, endMs, hours) {
  if (!(endMs > startMs)) return 0;
  const cfg = normalizeHours(hours);
  let { year: y, month: m, day: d } = zonedParts(startMs, cfg.timezone);
  const last = zonedParts(endMs, cfg.timezone);
  let totalMs = 0;
  for (let i = 0; i < MAX_DAYS_SCANNED; i++) {
    if (isBusinessDay(y, m, d, cfg)) {
      const w = dayWindow(y, m, d, cfg);
      const from = Math.max(startMs, w.open);
      const to = Math.min(endMs, w.close);
      if (to > from) totalMs += to - from;
    }
    if (y === last.year && m === last.month && d === last.day) break;
    ({ y, m, d } = nextDay(y, m, d));
  }
  return totalMs / MS_PER_MINUTE;
}

/** The instant at which `minutes` business minutes will have elapsed since `startMs`. */
function addBusinessMinutes(startMs, minutes, hours) {
  if (!(minutes > 0)) return startMs;
  const cfg = normalizeHours(hours);
  let remaining = minutes * MS_PER_MINUTE;
  let { year: y, month: m, day: d } = zonedParts(startMs, cfg.timezone);
  for (let i = 0; i < MAX_DAYS_SCANNED; i++) {
    if (isBusinessDay(y, m, d, cfg)) {
      const w = dayWindow(y, m, d, cfg);
      const from = Math.max(startMs, w.open);
      if (from < w.close) {
        const available = w.close - from;
        if (remaining <= available) return from + remaining;
        remaining -= available;
      }
    }
    ({ y, m, d } = nextDay(y, m, d));
  }
  throw new Error('addBusinessMinutes: no business hours found within 800 days - check your hours config');
}

// ---- src/config.js ----
/**
 * Central configuration loader. Reads environment variables (or an equivalent plain object)
 * and returns one validated config object shared by both workflows.
 *
 * SANDBOX_MODE defaults to TRUE: nothing is posted to Slack and nothing is written to HubSpot
 * until you explicitly set SANDBOX_MODE=false.
 */


const ENV_KEYS = [
  'SANDBOX_MODE',
  'SLA_MINUTES',
  'SLA_WARN_PCT',
  'LOOKBACK_HOURS',
  'REPORT_LOOKBACK_DAYS',
  'BUSINESS_TIMEZONE',
  'BUSINESS_START',
  'BUSINESS_END',
  'BUSINESS_WORKDAYS',
  'BUSINESS_HOLIDAYS',
  'EXCLUDED_LIFECYCLE_STAGES',
  'EXCLUDED_EMAIL_DOMAINS',
  'CLOCK_RESTARTS_ON_FORM_SUBMIT',
  'HUBSPOT_PORTAL_ID',
  'REPS_JSON',
  'FALLBACK_OWNER_ID',
  'OPEN_LEAD_STATUSES',
  'REASSIGN_EXISTING_OWNER',
  'ALERT_MAX_LEADS',
];

/**
 * Copy known keys out of an env-like object. Safe when n8n blocks env access
 * (N8N_BLOCK_ENV_ACCESS_IN_NODE=true): reads throw, we stop and fall back to safe defaults.
 */
function readEnv(source) {
  const env = {};
  for (const key of ENV_KEYS) {
    try {
      const v = source[key];
      if (v !== undefined && v !== null && v !== '') env[key] = v;
    } catch (e) {
      break;
    }
  }
  return env;
}

function toBool(value, fallback) {
  if (value === undefined || value === null || String(value).trim() === '') return fallback;
  return ['true', '1', 'yes', 'on'].includes(String(value).trim().toLowerCase());
}

/** Fail-safe: sandbox stays ON unless the value is an explicit "off" word. A typo like "flase" keeps it ON. */
function toSandbox(value) {
  if (value === undefined || value === null || String(value).trim() === '') return true;
  return !['false', '0', 'no', 'off'].includes(String(value).trim().toLowerCase());
}

function toNum(value, fallback, name) {
  if (value === undefined || value === null || String(value).trim() === '') return fallback;
  const n = Number(value);
  if (!Number.isFinite(n)) throw new Error(`${name} must be a number, got "${value}"`);
  return n;
}

function toList(value, fallback) {
  const raw = value === undefined || value === null ? fallback : String(value);
  return raw.split(',').map((s) => s.trim()).filter(Boolean);
}

function parseReps(json) {
  if (json === undefined || json === null || String(json).trim() === '') return [];
  let reps;
  try {
    reps = typeof json === 'string' ? JSON.parse(json) : json;
  } catch (e) {
    throw new Error(`REPS_JSON is not valid JSON: ${e.message}`);
  }
  if (!Array.isArray(reps)) throw new Error('REPS_JSON must be a JSON array of rep objects');
  const seen = new Set();
  return reps.map((r, i) => {
    if (!r || r.id === undefined || r.id === null || !r.name) {
      throw new Error(`REPS_JSON[${i}] needs at least "id" (HubSpot owner ID) and "name"`);
    }
    const id = String(r.id);
    if (seen.has(id)) throw new Error(`REPS_JSON has a duplicate rep id: ${id}`);
    seen.add(id);
    return {
      id,
      name: String(r.name),
      active: r.active !== false,
      maxOpenLeads: Number.isFinite(Number(r.maxOpenLeads)) && r.maxOpenLeads !== null ? Number(r.maxOpenLeads) : null,
      ooo: Array.isArray(r.ooo) ? r.ooo : [],
    };
  });
}

function loadConfig(env) {
  const e = env || {};
  const cfg = {
    sandbox: toSandbox(e.SANDBOX_MODE),
    slaMinutes: toNum(e.SLA_MINUTES, 15, 'SLA_MINUTES'),
    warnPct: toNum(e.SLA_WARN_PCT, 0.75, 'SLA_WARN_PCT'),
    lookbackHours: toNum(e.LOOKBACK_HOURS, 96, 'LOOKBACK_HOURS'),
    reportLookbackDays: toNum(e.REPORT_LOOKBACK_DAYS, 7, 'REPORT_LOOKBACK_DAYS'),
    hours: {
      timezone: e.BUSINESS_TIMEZONE || 'America/New_York',
      startTime: e.BUSINESS_START || '09:00',
      endTime: e.BUSINESS_END || '17:00',
      workdays: toList(e.BUSINESS_WORKDAYS, '1,2,3,4,5').map(Number),
      holidays: toList(e.BUSINESS_HOLIDAYS, ''),
    },
    excludedLifecycleStages: toList(e.EXCLUDED_LIFECYCLE_STAGES, 'customer,evangelist,other').map((s) => s.toLowerCase()),
    excludedEmailDomains: toList(e.EXCLUDED_EMAIL_DOMAINS, '').map((s) => s.toLowerCase().replace(/^@/, '')),
    clockRestartsOnFormSubmit: toBool(e.CLOCK_RESTARTS_ON_FORM_SUBMIT, true),
    portalId: e.HUBSPOT_PORTAL_ID ? String(e.HUBSPOT_PORTAL_ID) : '',
    reps: parseReps(e.REPS_JSON),
    fallbackOwnerId: e.FALLBACK_OWNER_ID ? String(e.FALLBACK_OWNER_ID) : '',
    openLeadStatuses: toList(e.OPEN_LEAD_STATUSES, 'NEW,OPEN,IN_PROGRESS,ATTEMPTED_TO_CONTACT'),
    reassignExistingOwner: toBool(e.REASSIGN_EXISTING_OWNER, false),
    alertMaxLeads: toNum(e.ALERT_MAX_LEADS, 10, 'ALERT_MAX_LEADS'),
  };

  if (!(cfg.slaMinutes > 0)) throw new Error('SLA_MINUTES must be greater than 0');
  if (!(cfg.warnPct > 0 && cfg.warnPct <= 1)) throw new Error('SLA_WARN_PCT must be between 0 (exclusive) and 1');
  if (!(cfg.lookbackHours > 0)) throw new Error('LOOKBACK_HOURS must be greater than 0');
  if (!(cfg.reportLookbackDays > 0)) throw new Error('REPORT_LOOKBACK_DAYS must be greater than 0');
  normalizeHours(cfg.hours); // throws a readable error for bad time zone / hours / workdays
  return cfg;
}

// ---- src/hubspot.js ----
/**
 * HubSpot helpers: build API request bodies, normalize API responses into leads and touches.
 * Pure functions only - the n8n HTTP Request nodes do the actual network calls.
 *
 * NOTE: property names below are standard HubSpot CRM properties, but portals differ.
 * Verify them in your own portal (see docs/SETUP.md > "Verify property names").
 */

const LEAD_PROPERTIES = [
  'createdate',
  'recent_conversion_date',
  'recent_conversion_event_name',
  'firstname',
  'lastname',
  'email',
  'company',
  'hubspot_owner_id',
  'hs_lead_status',
  'lifecyclestage',
  'hs_latest_sequence_enrolled_date',
];

const ENGAGEMENT_TYPES = ['calls', 'emails', 'meetings'];

const DETAIL_PROPERTIES = {
  calls: ['hs_timestamp', 'hs_call_direction'],
  emails: ['hs_timestamp', 'hs_email_direction'],
  meetings: ['hs_timestamp', 'hs_createdate', 'hs_meeting_outcome'],
};

function assertResults(body, label) {
  if (!body || !Array.isArray(body.results)) {
    throw new Error(
      `HubSpot response for "${label}" did not contain a results array: ${JSON.stringify(body).slice(0, 300)}`
    );
  }
}

/** HubSpot returns ISO strings or epoch-ms strings depending on endpoint. Accept both. */
function parseHsDate(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const s = String(value).trim();
  if (/^\d{10,}$/.test(s)) return Number(s);
  const t = Date.parse(s);
  return Number.isFinite(t) ? t : null;
}

/** Search body: contacts created (or re-submitted via form) inside the lookback window. */
function buildLeadSearchBody(cfg, mode, nowMs) {
  const sinceMs = mode === 'report' ? nowMs - cfg.reportLookbackDays * 86400000 : nowMs - cfg.lookbackHours * 3600000;
  const since = String(Math.floor(sinceMs));
  const filterGroups = [{ filters: [{ propertyName: 'createdate', operator: 'GTE', value: since }] }];
  if (cfg.clockRestartsOnFormSubmit) {
    filterGroups.push({ filters: [{ propertyName: 'recent_conversion_date', operator: 'GTE', value: since }] });
  }
  return {
    filterGroups,
    sorts: [{ propertyName: 'createdate', direction: 'DESCENDING' }],
    properties: LEAD_PROPERTIES,
    limit: 100,
  };
}

/** Search body used by round-robin to count each rep's currently open leads. */
function buildOpenLeadSearchBody(cfg) {
  const ids = cfg.reps.map((r) => String(r.id));
  return {
    filterGroups: [
      {
        filters: [
          { propertyName: 'hubspot_owner_id', operator: 'IN', values: ids.length ? ids : ['0'] },
          { propertyName: 'hs_lead_status', operator: 'IN', values: cfg.openLeadStatuses },
        ],
      },
    ],
    properties: ['hubspot_owner_id'],
    limit: 100,
  };
}

/** Turn one HubSpot contact search result into a lead, or null if it should be skipped. */
function normalizeLead(result, cfg) {
  const p = (result && result.properties) || {};
  const createdAt = parseHsDate(p.createdate);
  const recentConversion = parseHsDate(p.recent_conversion_date);

  const stage = String(p.lifecyclestage || '').toLowerCase();
  if (stage && cfg.excludedLifecycleStages.includes(stage)) return null;

  const email = p.email ? String(p.email) : '';
  const domain = email.includes('@') ? email.split('@').pop().toLowerCase() : '';
  if (domain && cfg.excludedEmailDomains.includes(domain)) return null;

  let clockStartMs = createdAt;
  if (cfg.clockRestartsOnFormSubmit && recentConversion && (!createdAt || recentConversion > createdAt)) {
    clockStartMs = recentConversion;
  }
  if (!clockStartMs) return null;

  const eventName = p.recent_conversion_event_name ? String(p.recent_conversion_event_name) : '';
  const name = [p.firstname, p.lastname].filter(Boolean).join(' ').trim();

  return {
    id: String(result.id),
    name: name || email || `Contact ${result.id}`,
    email,
    company: p.company ? String(p.company) : '',
    ownerId: p.hubspot_owner_id ? String(p.hubspot_owner_id) : null,
    leadStatus: p.hs_lead_status || null,
    lifecycleStage: stage || null,
    createdAtMs: createdAt,
    clockStartMs,
    sequenceEnrolledAtMs: parseHsDate(p.hs_latest_sequence_enrolled_date),
    source: eventName ? `Form: ${eventName}` : 'New contact',
  };
}

function normalizeLeads(results, cfg) {
  return results.map((r) => normalizeLead(r, cfg)).filter(Boolean);
}

/** assocResponses: HubSpot v4 batch-read association responses, in ENGAGEMENT_TYPES order. */
function buildAssocMap(assocResponses) {
  const map = {};
  ENGAGEMENT_TYPES.forEach((type, i) => {
    assertResults(assocResponses[i], `associations contacts->${type}`);
    map[type] = {};
    for (const row of assocResponses[i].results) {
      const from = row.from && row.from.id !== undefined ? String(row.from.id) : null;
      if (!from) continue;
      map[type][from] = (row.to || []).map((t) => String(t.toObjectId));
    }
  });
  return map;
}

/**
 * One batch-read request per type per 100 engagement IDs. Always returns at least one item so the
 * workflow keeps flowing when nobody has been touched yet (that is the case we care about most).
 */
function buildDetailRequests(assocMap, chunkSize) {
  const size = chunkSize || 100;
  const requests = [];
  for (const type of ENGAGEMENT_TYPES) {
    const ids = new Set();
    Object.values(assocMap[type] || {}).forEach((arr) => arr.forEach((id) => ids.add(id)));
    const list = Array.from(ids);
    for (let i = 0; i < list.length; i += size) {
      requests.push({
        objectType: type,
        skip: false,
        body: { properties: DETAIL_PROPERTIES[type], inputs: list.slice(i, i + size).map((id) => ({ id })) },
      });
    }
  }
  if (!requests.length) {
    requests.push({ objectType: 'calls', skip: true, body: { properties: DETAIL_PROPERTIES.calls, inputs: [] } });
  }
  requests[0].assocMap = assocMap;
  return requests;
}

/** Normalize one engagement into a touch, or null if it should not count as outreach. */
function touchFromEngagement(type, props) {
  const p = props || {};
  if (type === 'calls') {
    if (String(p.hs_call_direction || '').toUpperCase() === 'INBOUND') return null;
    const at = parseHsDate(p.hs_timestamp);
    return at ? { type: 'call', at } : null;
  }
  if (type === 'emails') {
    const dir = String(p.hs_email_direction || '').toUpperCase();
    if (dir === 'INCOMING_EMAIL' || dir === 'FORWARDED_EMAIL' || dir === 'INBOUND') return null;
    const at = parseHsDate(p.hs_timestamp);
    return at ? { type: 'email', at } : null;
  }
  if (type === 'meetings') {
    // A meeting counts when it is booked/logged (creation time), not when it takes place.
    const at = parseHsDate(p.hs_createdate) || parseHsDate(p.hs_timestamp);
    return at ? { type: 'meeting', at } : null;
  }
  return null;
}

/**
 * @param assocMap          output of buildAssocMap
 * @param detailRequests    the request items (same order as the responses)
 * @param detailResponses   HubSpot batch-read responses
 * @returns { [contactId]: touches[] }
 */
function collectTouches(assocMap, detailRequests, detailResponses) {
  const engagements = { calls: {}, emails: {}, meetings: {} };
  detailResponses.forEach((resp, i) => {
    const type = detailRequests[i].objectType;
    assertResults(resp, `read ${type}`);
    for (const row of resp.results) {
      const touch = touchFromEngagement(type, row.properties);
      if (touch) engagements[type][String(row.id)] = touch;
    }
  });
  const byLead = {};
  for (const type of ENGAGEMENT_TYPES) {
    const perLead = assocMap[type] || {};
    for (const leadId of Object.keys(perLead)) {
      for (const engagementId of perLead[leadId]) {
        const touch = engagements[type][engagementId];
        if (touch) (byLead[leadId] = byLead[leadId] || []).push(touch);
      }
    }
  }
  return byLead;
}

// ---- node logic (scripts/node-code/wf1-load-config.js) ----
// Code node: "Load Config" (Run Once for All Items)
// Reads settings from environment variables (see docs/CONFIGURATION.md) and builds the HubSpot lead search body.
// If your n8n blocks $env access, hard-code settings here instead, e.g. { SANDBOX_MODE: 'true', SLA_MINUTES: '15' }.
const OVERRIDES = {};

const env = Object.assign(readEnv($env), OVERRIDES);
const cfg = loadConfig(env);
const mode = $input.first().json.mode === 'report' ? 'report' : 'monitor';
const nowMs = Date.now();

return [{ json: { mode, cfg, searchBody: buildLeadSearchBody(cfg, mode, nowMs) } }];

